var tokenDescription = [numTokens]string{
	TIndent:  "an indented line",
	TDedent:  "the end of the indented lines",
	TName:    "a name",
	TInteger: "an integer",
	TString:  "a string",
	TLabel:   "a label",
	TNewline: "the end of the line",
}

// tokenNoSpaceBefore and tokenNoSpaceAfter mark the tokens joined to the token before or after them.
var tokenNoSpaceBefore = [numTokens]bool{TRParen: true, TLBrace: true, TRBrace: true, TComma: true, TColon: true, TDot: true, TLBracket: true, TRBracket: true}

var tokenNoSpaceAfter = [numTokens]bool{TLParen: true, TLBrace: true, TDot: true, TLBracket: true}

// tokenScanned marks the tokens the DFA only starts; scanRest reads the rest of each.
var tokenScanned = [numTokens]bool{TString: true}

func (lx *lexer) scanRest(kind T, start int) int {
	switch kind {
	case TString:
		return lx.scanString(start)
	}
	panic(diag.Internal("token %d is not scanned", kind))
}
